Given an array arr[] of positive integers and an integer k. Find the maximum value for each contiguous subarray of size k.Return an array of maximum values corresponding to each contiguous subarray.Examples : Input: arr[] = [1, 2, 3, 1, 4, 5, 2, 3, 6], k = 3Output: [3, 3, 4, 5, 5, 5, 6] Explanation: 1st contiguous subarray = [1 2 3] max = 32nd contiguous subarray = [2 3 1] max = 33rd contiguous subarray = [3 1 4] max = 44th contiguous subarray = [1 4 5] max = 55th contiguous subarray = [4 5 2] max = 56th contiguous subarray = [5 2 3] max = 57th contiguous subarray = [2 3 6] max = 6Input: arr[] = [5, 1, 3, 4, 2, 6], k = 1Output: [5, 1, 3, 4, 2, 6]Explanation: When k = 1, each element in the array is its own subarray, so the output is simply the same array.Try It YourselfTable of Content[Naive Approach] - Using Nested Loops - O(n * k) Time and O(1) Space[Better Approach] - Using Max-Heap - (n * log n) Time and O(n) Space[Expected Approach] - Using Deque - O(n) Time and O(k) Space[Naive Approach] - Using Nested Loops - O(n * k) Time and O(1) SpaceThe idea is to run the nested loops, the outer loop will mark the starting point of the subarray of length k, and the inner loop will run from the starting index to index + k, and print the maximum element among these k elements. 
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> maxOfSubarrays(vector<int>& arr, int k) {
    int n = arr.size();

    // to store the results
    vector<int> res;

    for (int i = 0; i <= n - k; i++) {

        // Find maximum of subarray beginning
        // with arr[i]
        int max = arr[i];
        for (int j = 1; j < k; j++) {
            if (arr[i + j] > max)
                max = arr[i + j];
        }
        res.push_back(max);
    }

    return res;
}

int main() {
    vector<int> arr = { 1, 2, 3, 1, 4, 5, 2, 3, 6 };
    int k = 3;
    vector<int> res = maxOfSubarrays(arr, k);
    for (int maxVal : res) {
        cout << maxVal << " ";
    }
    return 0;
}


